"""Migration of the Meridian CRM 4.2 ``order_fulfilment`` workflow."""

from __future__ import annotations

from decimal import Decimal, InvalidOperation
from typing import Any, Callable


Guard = Callable[[dict, dict], bool]


def _numeric(value: Any) -> Decimal:
    """Apply the legacy empty-string-to-zero numeric coercion."""
    if value is None or value == "":
        return Decimal(0)
    if isinstance(value, bool):
        return Decimal(int(value))
    try:
        return Decimal(str(value))
    except (InvalidOperation, ValueError):
        return Decimal(0)


def _approve_guard(record: dict, tables: dict) -> bool:
    # NVL(TOT_AMT, 0) > 0
    return _numeric(record.get("TOT_AMT", "")) > Decimal(0)


def _lookup(
    tables: dict,
    table_name: str,
    key_column: str,
    key_value: Any,
    output_column: str,
) -> Any:
    """Return the first matching live row's value, or the legacy empty string."""
    rows = tables.get(table_name, [])
    if not isinstance(rows, list):
        return ""

    for row in rows:
        if not isinstance(row, dict):
            continue
        if row.get("DEL_FLG", "") == "Y":
            continue
        if row.get(key_column, "") == key_value:
            value = row.get(output_column, "")
            return "" if value is None else value

    return ""


def _account_cancel_guard(record: dict, tables: dict) -> bool:
    # LOOKUP(ACCT_MASTER, ACCT_ID, ACCT_ID, CRED_HOLD) <> 'Y'
    credit_hold = _lookup(
        tables,
        "ACCT_MASTER",
        "ACCT_ID",
        record.get("ACCT_ID", ""),
        "CRED_HOLD",
    )
    return credit_hold != "Y"


# Document order from order_fulfilment.xml is significant.
_TRANSITIONS: tuple[
    tuple[str, str, str, Guard | None, tuple[str, ...], tuple[str, ...]], ...
] = (
    ("E", "A", "approve", _approve_guard, ("ORD_APPR",), ()),
    ("A", "S", "ship", None, ("ORD_SHIP",), ("shipped",)),
    ("S", "I", "invoice", None, ("ORD_INV",), ()),
    ("E", "X", "cancel", None, ("ORD_CANC",), ()),
    ("A", "X", "cancel", _account_cancel_guard, ("ORD_CANC",), ()),
    ("I", "X", "cancel", None, ("ORD_CANC_INV",), ("credit_note",)),
)


def fire(state: str, event: str, record: dict, tables: dict) -> dict:
    """Fire one workflow event using legacy first-match semantics."""
    record_copy = dict(record)

    for (
        from_state,
        to_state,
        transition_event,
        guard,
        audits,
        notifies,
    ) in _TRANSITIONS:
        if state != from_state or event != transition_event:
            continue
        if guard is not None and not guard(record_copy, tables):
            continue

        return {
            "state": to_state,
            "record": record_copy,
            "audits": list(audits),
            "notifies": list(notifies),
            "matched": True,
        }

    return {
        "state": state,
        "record": record_copy,
        "audits": ["WF_NOMATCH"],
        "notifies": [],
        "matched": False,
    }
